import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import {
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { cn } from "./lib/cn";
import "./shared/segmented-plate.css";

/** With an icon, the option shows only the icon and `label` becomes its accessible name and tooltip. */
export type SegmentedOption = { value: string; label: string; icon?: ReactNode };

export function SegmentedControl({
  label,
  value,
  onValueChange,
  options,
  className,
}: {
  label: string;
  value: string;
  onValueChange: (value: string) => void;
  options: readonly SegmentedOption[];
  className?: string;
}) {
  const group = useRef<HTMLDivElement>(null);
  const [initialValue] = useState(value);
  const [indicator, setIndicator] = useState<{
    left: number;
    top: number;
    width: number;
    height: number;
  } | null>(null);

  useLayoutEffect(() => {
    const element = group.current;
    if (!element) return;
    const measure = () => {
      const active = element.querySelector<HTMLElement>('[aria-checked="true"]');
      setIndicator(
        active
          ? {
              left: active.offsetLeft,
              top: active.offsetTop,
              width: active.offsetWidth,
              height: active.offsetHeight,
            }
          : null,
      );
    };
    measure();
    const resize = new ResizeObserver(measure);
    resize.observe(element);
    element
      .querySelectorAll('[role="radio"]')
      .forEach((item) => resize.observe(item));
    return () => resize.disconnect();
  }, [value, options]);

  function move(event: KeyboardEvent<HTMLDivElement>) {
    const index = options.findIndex((item) => item.value === value);
    const next =
      event.key === "ArrowRight" || event.key === "ArrowDown"
        ? (index + 1) % options.length
        : event.key === "ArrowLeft" || event.key === "ArrowUp"
          ? (index - 1 + options.length) % options.length
          : -1;
    if (next < 0) return;
    event.preventDefault();
    onValueChange(options[next].value);
    group.current
      ?.querySelectorAll<HTMLButtonElement>('[role="radio"]')
      [next]?.focus();
  }

  return (
    <div
      ref={group}
      role="radiogroup"
      aria-label={label}
      data-slot="segmented"
      onKeyDown={move}
      className={cn(
        // Too many options for a narrow screen scroll sideways instead of spilling out.
        "relative inline-flex max-w-full overflow-x-auto rounded-touch bg-sunken p-[3px] shadow-sunken [scrollbar-width:none]",
        className,
      )}
    >
      {indicator && (
        <span
          aria-hidden="true"
          data-slot="segmented-indicator"
          style={{
            width: indicator.width,
            height: indicator.height,
            transform: `translate(${indicator.left}px, ${indicator.top}px)`,
          }}
        >
          <span
            key={value}
            data-slot="segmented-plate"
            data-moved={value !== initialValue}
          />
        </span>
      )}
      {options.map((option) => {
        const selected = option.value === value;
        return (
          <button
            key={option.value}
            type="button"
            role="radio"
            aria-checked={selected}
            tabIndex={selected ? 0 : -1}
            aria-label={option.icon ? option.label : undefined}
            title={option.icon ? option.label : undefined}
            onClick={() => onValueChange(option.value)}
            className="relative z-10 inline-flex shrink-0 h-[calc(var(--control-height)-6px)] min-w-10 items-center justify-center rounded-[calc(var(--radius-touch)-3px)] px-3 text-[13px] font-medium text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-0 focus-visible:outline-ring aria-checked:text-accent-foreground [&_svg]:size-4 [&_svg]:shrink-0"
          >
            {option.icon ?? option.label}
          </button>
        );
      })}
    </div>
  );
}

"use client";
import { useEffect, useId, useRef, useState, type ComponentProps } from "react";
import { cn } from "./lib/cn";
import { SegmentedControl } from "./segmented-control";
import "./unit-field.css";

/** A unit as a straight line from a base unit: base = value × factor + offset. */
export type FieldUnit = { value: string; label: string; factor: number; offset?: number; decimals?: number };

export const toBase = (value: number, unit: FieldUnit) => value * unit.factor + (unit.offset ?? 0);
export const fromBase = (base: number, unit: FieldUnit) => (base - (unit.offset ?? 0)) / unit.factor;

export type UnitFieldProps = Omit<ComponentProps<"div">, "defaultValue" | "onChange"> & {
  label: string;
  units: FieldUnit[];
  /** The amount in the base unit (the unit whose factor is 1). */
  value?: number;
  defaultValue?: number;
  onValueChange?: (base: number) => void;
  defaultUnit?: string;
};

/**
 * A number field with its unit beside it. Switching the unit converts the amount, and the figure counts across to
 * the new value rather than jumping, so it is clear the quantity is the same. The value is kept in a base unit, so
 * switching back and forth never drifts. Under reduced motion the figure changes at once.
 */
export function UnitField({ label, units, value, defaultValue = 0, onValueChange, defaultUnit, className, ...props }: UnitFieldProps) {
  const id = useId();
  const [own, setOwn] = useState(defaultValue);
  const base = value ?? own;
  const [unitValue, setUnitValue] = useState(defaultUnit ?? units[0].value);
  const unit = units.find((u) => u.value === unitValue) ?? units[0];
  const round = (n: number, u = unit) => Number(n.toFixed(u.decimals ?? 1));
  // What is typed, or the figure mid-count; otherwise the field shows the value, so outside changes appear.
  const [draft, setDraft] = useState<string | null>(null);
  const text = draft ?? String(round(fromBase(base, unit)));
  const tween = useRef(0);
  useEffect(() => () => cancelAnimationFrame(tween.current), []);

  const switchTo = (next: string) => {
    const to = units.find((u) => u.value === next)!;
    const from = Number(text) || 0;
    const target = round(fromBase(base, to), to);
    setUnitValue(next);
    cancelAnimationFrame(tween.current);
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) return setDraft(null);
    let start = -1;
    const step = (now: number) => {
      if (start < 0) start = now;
      const t = Math.min(1, (now - start) / 420);
      const eased = 1 - Math.pow(1 - t, 3);
      setDraft(String(Number((from + (target - from) * eased).toFixed(to.decimals ?? 1))));
      if (t < 1) tween.current = requestAnimationFrame(step);
      else {
        tween.current = 0;
        setDraft(null);
      }
    };
    tween.current = requestAnimationFrame(step);
  };

  const type = (next: string) => {
    setDraft(next);
    const number = Number(next);
    if (next.trim() === "" || !Number.isFinite(number)) return;
    const nextBase = toBase(number, unit);
    if (value === undefined) setOwn(nextBase);
    onValueChange?.(nextBase);
  };

  return (
    <div data-slot="unit-field" className={cn("grid gap-2", className)} {...props}>
      <label htmlFor={id} className="text-sm font-medium">
        {label}
      </label>
      <div className="flex items-center gap-2">
        <div data-slot="uf-box">
          <input
            id={id}
            inputMode="decimal"
            data-slot="uf-input"
            value={text}
            aria-describedby={`${id}-unit`}
            onBlur={() => setDraft(null)}
            onChange={(event) => type(event.target.value)}
          />
          <span id={`${id}-unit`} data-slot="uf-suffix">
            {unit.label}
          </span>
        </div>
        <SegmentedControl label={`${label} unit`} value={unit.value} onValueChange={switchTo} options={units.map((u) => ({ value: u.value, label: u.label }))} />
      </div>
    </div>
  );
}

/* Shared by billing-toggle.tsx, segmented-control.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Segmented control: one raised plate travels to the choice on the settle
     curve and stretches 7% toward it mid-flight, so selection reads as one
     object moving. Labels and the value change at once. */
  [data-slot="segmented-indicator"] {
    position: absolute;
    top: 0;
    left: 0;
    z-index: 0;
    pointer-events: none;
    transition:
      transform 320ms var(--ease-settle),
      width 320ms var(--ease-settle);
  }
  [data-slot="segmented-plate"] {
    display: block;
    width: 100%;
    height: 100%;
    /* Concentric with the track: its radius less the 3px inset. */
    border-radius: calc(var(--radius-touch) - 3px);
    background: var(--accent);
    box-shadow: var(--shadow-plate);
  }
  [data-slot="segmented-plate"][data-moved="true"] {
    animation: caliper-plate-stretch 320ms var(--ease-out);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="segmented-indicator"],
    [data-slot="segmented-plate"] {
      transition: none;
    }
    [data-slot="segmented-plate"][data-moved="true"] {
      animation: none;
    }
  }
}

/* unit-field.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Unit field: the figure and its unit read as one field; the unit switch sits beside it. */
  [data-slot="unit-field"] [data-slot="uf-box"] { display: flex; flex: 1; min-width: 0; align-items: center; height: var(--control-height); padding: 0 12px; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--background); transition: border-color var(--duration-fast) var(--ease-out); }
  [data-slot="unit-field"] [data-slot="uf-box"]:focus-within { border-color: var(--ring); box-shadow: 0 0 0 2px color-mix(in oklab, var(--ring) 30%, transparent); }
  [data-slot="unit-field"] [data-slot="uf-input"] { flex: 1; min-width: 0; border: 0; background: none; color: var(--foreground); font: inherit; font-size: 15px; font-variant-numeric: tabular-nums; outline: none; }
  [data-slot="unit-field"] [data-slot="uf-suffix"] { flex: none; color: var(--muted-foreground); font-size: 13px; }
}
